INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-1-1','1','Na Administração Pública, o princípio da legalidade significa que o agente público deve atuar conforme a lei e os limites jurídicos aplicáveis.','na administracao publica o principio da legalidade significa que o agente publico deve atuar conforme a lei e os limites juridicos aplicaveis','["agir conforme a lei e os limites jurídicos aplicáveis","agir segundo sua preferência pessoal","priorizar apenas costumes internos","dispensar regras quando houver urgência"]',0,'A legalidade vincula a atuação administrativa ao ordenamento jurídico.','CF/88, art. 37; material-base fornecido (Fundamentos da Administração Pública).',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-1-2','1','Um servidor recebe ordem verbal para praticar ato que contraria norma vigente. À luz do princípio da legalidade, a conduta correta é:','um servidor recebe ordem verbal para praticar ato que contraria norma vigente a luz do principio da legalidade a conduta correta e','["cumprir a ordem porque veio de superior hierárquico","recusar a prática ilegal e observar o ordenamento aplicável","cumprir e registrar posteriormente","agir conforme o costume do setor"]',1,'A atuação administrativa está vinculada ao ordenamento jurídico; ordem hierárquica não legitima conduta ilegal.','CF/88, art. 37, caput; princípio da legalidade.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-1-3','1','Em comparação com o particular, a legalidade administrativa significa que o agente público:','em comparacao com o particular a legalidade administrativa significa que o agente publico','["pode fazer tudo o que a lei não proíbe","atua apenas conforme autorização ou dever jurídico","possui liberdade equivalente à autonomia privada","pode afastar norma por conveniência"]',1,'Para o particular predomina a liberdade; para a Administração, a atuação exige fundamento no Direito.','CF/88, art. 37, caput; princípio da legalidade.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-1-4','1','A eficiência administrativa permite afastar uma exigência legal quando isso reduzir custos?','a eficiencia administrativa permite afastar uma exigencia legal quando isso reduzir custos','["sim, sempre que houver economia","sim, se houver urgência","não; eficiência deve ser harmonizada com a legalidade","não, porque eficiência não é princípio constitucional"]',2,'Os princípios administrativos devem ser aplicados conjuntamente; eficiência não autoriza descumprimento da lei.','CF/88, art. 37, caput.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-1','1','No conjunto LIMPE, a letra I corresponde à','no conjunto limpe a letra i corresponde a','["impessoalidade","isonomia tributária","informalidade","independência funcional"]',0,'LIMPE reúne Legalidade, Impessoalidade, Moralidade, Publicidade e Eficiência.','CF/88, art. 37; material-base fornecido (Fundamentos da Administração Pública).',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('adm-pdf-001','1','Segundo o art. 37, caput, da Constituição Federal, os princípios expressamente aplicáveis à Administração Pública são:','segundo o art 37 caput da constituicao federal os principios expressamente aplicaveis a administracao publica sao','["legalidade, impessoalidade, moralidade, publicidade e eficiência","legalidade, finalidade, continuidade, razoabilidade e eficiência","supremacia, indisponibilidade, autotutela, moralidade e eficiência","publicidade, economicidade, hierarquia, especialidade e legalidade","moralidade, igualdade, planejamento, motivação e eficiência"]',0,'O caput do art. 37 da Constituição Federal estabelece o conjunto conhecido pelo mnemônico LIMPE.','CF/88, art. 37; PDF de Administração Pública, seção sobre princípios constitucionais.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-2','1','Qual alternativa reúne somente princípios expressos no caput do art. 37 da Constituição?','qual alternativa reune somente principios expressos no caput do art 37 da constituicao','["legalidade, impessoalidade, moralidade, publicidade e eficiência","finalidade, motivação, razoabilidade, proporcionalidade e eficiência","supremacia, autotutela, publicidade, moralidade e legalidade","continuidade, especialidade, eficiência, publicidade e motivação"]',0,'O caput do art. 37 consagra expressamente o conjunto conhecido pelo mnemônico LIMPE.','CF/88, art. 37, caput.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-3','1','Os princípios do art. 37, caput, vinculam:','os principios do art 37 caput vinculam','["somente o Poder Executivo federal","apenas a Administração direta","a Administração direta e indireta de qualquer dos Poderes da União, Estados, DF e Municípios","somente servidores efetivos"]',2,'A própria redação constitucional atribui esse alcance aos princípios administrativos expressos.','CF/88, art. 37, caput.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-4','1','A inclusão expressa da eficiência no caput do art. 37 ocorreu com:','a inclusao expressa da eficiencia no caput do art 37 ocorreu com','["a Constituição de 1967","a Emenda Constitucional nº 19/1998","a Lei nº 9.784/1999","a Emenda Constitucional nº 45/2004"]',1,'A EC 19/1998 inseriu expressamente a eficiência entre os princípios constitucionais da Administração Pública.','CF/88, art. 37, caput; EC 19/1998.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-5','1','A moralidade administrativa exige que o agente público:','a moralidade administrativa exige que o agente publico','["observe apenas a literalidade das leis","atue segundo padrões éticos compatíveis com a função pública","priorize interesses particulares quando houver vantagem econômica","dispense justificativa para decisões discricionárias","substitua a lei por princípios morais pessoais"]',1,'A moralidade impõe padrões éticos à atuação administrativa e não se confunde com mera legalidade formal.','CF/88, art. 37; PDF de Administração Pública, princípio da moralidade.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-6','1','A publicidade administrativa está relacionada, entre outros aspectos, à:','a publicidade administrativa esta relacionada entre outros aspectos a','["transparência e possibilidade de controle da atuação administrativa","promoção pessoal do agente público","eliminação de todo e qualquer sigilo","dispensa de publicação dos atos externos","liberdade do administrador para ocultar informações públicas"]',0,'A publicidade favorece a transparência e o controle social, ressalvadas as hipóteses legais de sigilo.','CF/88, art. 37; PDF de Administração Pública.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-7','1','O princípio da eficiência busca, entre outros objetivos:','o principio da eficiencia busca entre outros objetivos','["aumentar a burocracia para evitar qualquer decisão","obter melhores resultados com uso racional dos recursos públicos","permitir atuação fora da lei quando houver economia","priorizar rapidez independentemente da qualidade","eliminar todos os controles administrativos"]',1,'Eficiência envolve qualidade dos resultados, racionalidade administrativa e redução de desperdícios, sempre em harmonia com os demais princípios.','CF/88, art. 37; PDF de Administração Pública, princípio da eficiência.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-8','1','A busca pela eficiência permite à Administração Pública:','a busca pela eficiencia permite a administracao publica','["descumprir a legalidade para alcançar melhores resultados","afastar a moralidade quando houver economia","harmonizar melhores resultados com os demais princípios administrativos","eliminar a publicidade dos atos","substituir normas jurídicas por metas administrativas"]',2,'O material ressalta que eficiência não autoriza o abandono da legalidade, impessoalidade, moralidade ou publicidade.','PDF de Administração Pública, princípio da eficiência.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-9','1','As denominadas ''pedras de toque'' do regime jurídico-administrativo são:','as denominadas pedras de toque do regime juridico administrativo sao','["supremacia do interesse público e indisponibilidade do interesse público","legalidade e publicidade","moralidade e eficiência","autotutela e especialidade","continuidade e motivação"]',0,'Esses dois postulados são apontados pela doutrina como bases estruturantes do regime jurídico-administrativo.','PDF de Administração Pública, regime jurídico-administrativo.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-10','1','A supremacia do interesse público expressa a ideia de que:','a supremacia do interesse publico expressa a ideia de que','["o interesse privado nunca possui proteção jurídica","a atuação administrativa pode envolver prerrogativas voltadas à proteção do interesse coletivo","todo interesse estatal é automaticamente legítimo","a Administração pode agir sem fundamento legal","o particular não possui direitos perante o Estado"]',1,'A supremacia fundamenta prerrogativas públicas, mas sua utilização continua submetida ao ordenamento jurídico e aos direitos dos administrados.','PDF de Administração Pública, regime jurídico-administrativo.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-12','1','Um princípio pode ser considerado implícito na Constituição quando:','um principio pode ser considerado implicito na constituicao quando','["seu nome aparece obrigatoriamente no caput do art. 37","decorre da interpretação do sistema jurídico mesmo sem denominação expressa no texto constitucional","não possui qualquer fundamento jurídico","só existe se constar de decreto municipal","for criado por decisão administrativa isolada"]',1,'Princípios implícitos são reconhecidos a partir da interpretação de normas, valores constitucionais e do sistema jurídico.','PDF de Administração Pública, princípios expressos e implícitos.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-13','1','Qual dos seguintes é apresentado no material como princípio implícito/reconhecido na Constituição, embora possa aparecer expressamente em outras leis?','qual dos seguintes e apresentado no material como principio implicito reconhecido na constituicao embora possa aparecer expressamente em outras leis','["segurança jurídica","publicidade","moralidade","eficiência","impessoalidade"]',0,'O material utiliza a segurança jurídica como exemplo de princípio implícito na Constituição e expresso, por exemplo, na Lei 9.784/1999.','PDF de Administração Pública; Lei 9.784/1999, art. 2º.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-14','1','A classificação de um princípio como expresso ou implícito pode depender:','a classificacao de um principio como expresso ou implicito pode depender','["da norma jurídica usada como referência","somente do município envolvido","exclusivamente da doutrina estrangeira","da preferência do agente público","do valor financeiro do ato"]',0,'Um princípio pode ser implícito na Constituição e expressamente previsto em determinada lei infraconstitucional.','PDF de Administração Pública; referências à Lei 14.133/2021 e Lei 9.784/1999.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-15','1','Na Lei nº 14.133/2021, o princípio da igualdade é tratado como:','na lei n 14 133 2021 o principio da igualdade e tratado como','["princípio expresso no art. 5º da lei","princípio inexistente em licitações","princípio exclusivo da Constituição, sem previsão legal","princípio incompatível com competição","princípio aplicável apenas a contratos privados"]',0,'O material destaca que a Lei 14.133/2021 expressamente contempla a igualdade entre os princípios aplicáveis às licitações e contratos.','Lei 14.133/2021, art. 5º; PDF de Administração Pública.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-16','1','Entre os princípios expressamente relacionados no art. 5º da Lei nº 14.133/2021 encontra-se:','entre os principios expressamente relacionados no art 5 da lei n 14 133 2021 encontra se','["vinculação ao edital","supremacia do interesse privado","liberdade de contratação sem critérios","sigilo absoluto","ausência de motivação"]',0,'A Lei de Licitações inclui, entre outros, a vinculação ao edital, julgamento objetivo, planejamento, transparência, motivação e segurança jurídica.','Lei 14.133/2021, art. 5º; PDF de Administração Pública.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-17','1','Segundo o material, a Lei nº 9.784/1999 menciona expressamente, entre outros, os princípios da:','segundo o material a lei n 9 784 1999 menciona expressamente entre outros os principios da','["finalidade, motivação, razoabilidade, proporcionalidade e segurança jurídica","soberania, cidadania e pluralismo político","livre iniciativa e propriedade privada","anualidade e universalidade orçamentária","hierarquia e supremacia privada"]',0,'O art. 2º da Lei 9.784/1999 contém esse conjunto de princípios, entre outros.','Lei 9.784/1999, art. 2º; PDF de Administração Pública.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-18','1','O princípio da finalidade exige que a atuação administrativa:','o principio da finalidade exige que a atuacao administrativa','["seja orientada à finalidade prevista pelo ordenamento e ao interesse público","busque beneficiar pessoalmente o agente","tenha sempre finalidade econômica","dispense previsão legal","priorize interesses partidários"]',0,'A finalidade decorre, entre outros fundamentos, da impessoalidade e exige que a competência seja utilizada para o fim jurídico adequado.','PDF de Administração Pública, princípios reconhecidos.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-19','1','Quando uma autoridade utiliza competência administrativa para perseguir pessoalmente um adversário, há violação especialmente relacionada à:','quando uma autoridade utiliza competencia administrativa para perseguir pessoalmente um adversario ha violacao especialmente relacionada a','["impessoalidade e finalidade","eficiência apenas","publicidade apenas","continuidade apenas","especialidade apenas"]',0,'O exercício da competência para perseguição pessoal desvia a atuação administrativa de sua finalidade pública.','PDF de Administração Pública, impessoalidade e finalidade.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-20','1','O princípio da autotutela permite à Administração:','o principio da autotutela permite a administracao','["anular atos ilegais e revogar atos por conveniência e oportunidade, nos limites jurídicos","impedir qualquer controle judicial","revogar atos ilegais apenas quando houver autorização do particular","declarar todos os seus atos irrevogáveis","dispensar a observância da legalidade"]',0,'Autotutela envolve controle dos próprios atos: invalidação por ilegalidade e revogação por razões de mérito administrativo, quando cabível.','PDF de Administração Pública, princípio da autotutela.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-21','1','A anulação de um ato administrativo está associada principalmente à existência de:','a anulacao de um ato administrativo esta associada principalmente a existencia de','["ilegalidade","mera inconveniência","mudança de preferência política","falta de interesse privado","aumento de eficiência"]',0,'A anulação decorre de vício de legalidade; não se confunde com revogação, que se relaciona ao mérito administrativo.','PDF de Administração Pública, autotutela.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-22','1','A revogação de um ato administrativo, quando juridicamente cabível, relaciona-se à:','a revogacao de um ato administrativo quando juridicamente cabivel relaciona se a','["conveniência e oportunidade","existência obrigatória de ilegalidade","declaração judicial de nulidade","ausência absoluta de discricionariedade","impossibilidade de alteração do ato"]',0,'A revogação incide sobre o mérito administrativo, quando presentes os pressupostos jurídicos para tanto.','PDF de Administração Pública, autotutela.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-23','1','O princípio da tutela administrativa refere-se ao controle exercido:','o principio da tutela administrativa refere se ao controle exercido','["pela Administração direta sobre entidades da Administração indireta, nos limites legais","pelo Judiciário sobre qualquer cidadão","pelo particular sobre o órgão público","por um servidor sobre outro sem hierarquia","exclusivamente por empresas privadas"]',0,'Tutela não se confunde com autotutela: trata do controle finalístico sobre entidades da Administração indireta.','PDF de Administração Pública, princípios de controle administrativo.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-24','1','A tutela administrativa não significa:','a tutela administrativa nao significa','["subordinação hierárquica irrestrita entre Administração direta e entidade descentralizada","controle finalístico previsto em lei","fiscalização nos limites estabelecidos pelo ordenamento","acompanhamento da atuação da entidade","exercício de controle sobre entidade da Administração indireta"]',0,'A tutela é controle finalístico; não se confunde com relação hierárquica própria da desconcentração.','PDF de Administração Pública, tutela e organização administrativa.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-25','1','O princípio da continuidade do serviço público está ligado à ideia de que:','o principio da continuidade do servico publico esta ligado a ideia de que','["serviços públicos devem ser prestados de modo a evitar interrupções indevidas","todo serviço público deve funcionar sem qualquer pausa técnica","nenhum serviço pode ser alterado","o servidor jamais pode ser substituído","o particular deve assumir todo serviço estatal"]',0,'A continuidade busca preservar a prestação adequada dos serviços públicos, admitidas interrupções juridicamente justificadas.','PDF de Administração Pública, princípios reconhecidos.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-26','1','O princípio da especialidade relaciona-se especialmente à ideia de que:','o principio da especialidade relaciona se especialmente a ideia de que','["entidades administrativas devem atuar dentro das finalidades para as quais foram instituídas","qualquer órgão pode executar qualquer atividade sem limite","a Administração indireta não possui finalidade definida","todo servidor deve exercer todas as funções","as entidades privadas não possuem objeto definido"]',0,'A especialidade limita a atuação da entidade às finalidades legais que justificaram sua criação, relacionando-se à descentralização administrativa.','PDF de Administração Pública, princípio da especialidade.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-27','1','A presunção de legitimidade dos atos administrativos é considerada, em regra:','a presuncao de legitimidade dos atos administrativos e considerada em regra','["relativa, admitindo prova em contrário","absoluta e impossível de contestar","inexistente","aplicável apenas aos atos privados","dependente de aprovação judicial prévia"]',0,'A presunção de legitimidade é relativa, de modo que pode ser afastada mediante demonstração da ilegalidade ou irregularidade.','PDF de Administração Pública, atributos dos atos administrativos.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-28','1','O princípio da razoabilidade busca, em termos gerais, que a decisão administrativa:','o principio da razoabilidade busca em termos gerais que a decisao administrativa','["seja coerente e adequada diante das circunstâncias concretas","seja sempre a mais severa possível","ignore os fatos do caso concreto","priorize exclusivamente a economia","dispense fundamentação"]',0,'Razoabilidade atua como parâmetro de adequação e coerência da atuação administrativa diante da situação concreta.','PDF de Administração Pública, princípios implícitos/reconhecidos.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-29','1','A proporcionalidade exige, entre outros aspectos, que uma medida administrativa restritiva:','a proporcionalidade exige entre outros aspectos que uma medida administrativa restritiva','["seja adequada, necessária e equilibrada em relação à finalidade buscada","seja sempre máxima, independentemente dos efeitos","seja escolhida sem considerar alternativas menos gravosas","ignore os direitos individuais","seja aplicada sem finalidade pública"]',0,'A proporcionalidade funciona como parâmetro para evitar restrições excessivas e exige relação equilibrada entre meios e fins.','PDF de Administração Pública, proporcionalidade.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-31','1','A segurança jurídica busca favorecer:','a seguranca juridica busca favorecer','["estabilidade, previsibilidade e proteção da confiança legítima nas relações jurídicas","mudanças administrativas arbitrárias","incerteza permanente na atuação estatal","ausência de regras","revogação indiscriminada de situações consolidadas"]',0,'Segurança jurídica protege a estabilidade das relações e a previsibilidade da atuação estatal.','PDF de Administração Pública; Lei 9.784/1999.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-32','1','No contexto administrativo, a igualdade exige que a Administração:','no contexto administrativo a igualdade exige que a administracao','["trate situações equivalentes de forma compatível e estabeleça diferenciações apenas quando juridicamente justificadas","favoreça sempre os grupos politicamente mais fortes","trate todos de maneira idêntica mesmo quando as situações forem juridicamente distintas","ignore critérios legais","substitua critérios objetivos por preferências pessoais"]',0,'A igualdade impede privilégios ou discriminações arbitrárias e admite diferenciações quando fundadas em critérios juridicamente pertinentes.','Lei 14.133/2021, art. 5º; PDF de Administração Pública.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-33','1','O formalismo moderado no processo administrativo busca:','o formalismo moderado no processo administrativo busca','["evitar que formalidades sejam tratadas como fim em si mesmas, preservando segurança e direitos dos interessados","eliminar toda formalidade","dispensar contraditório e ampla defesa","tornar o processo necessariamente mais burocrático","substituir a lei por informalidade absoluta"]',0,'O material destaca formas simples e suficientes, sem transformar formalidades em obstáculos desvinculados da finalidade do processo.','PDF de Administração Pública, formalismo moderado.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-34','1','A criação de uma autarquia, segundo a Constituição Federal, depende de:','a criacao de uma autarquia segundo a constituicao federal depende de','["lei específica","simples portaria administrativa","contrato privado","decreto municipal sem base legal","ato interno de qualquer servidor"]',0,'O art. 37, XIX, da Constituição determina que autarquia seja criada por lei específica.','CF/88, art. 37, XIX; PDF de Administração Pública.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-35','1','Quanto à empresa pública e à sociedade de economia mista, a Constituição prevê:','quanto a empresa publica e a sociedade de economia mista a constituicao preve','["lei específica autorizando sua instituição","criação automática por decreto sem lei","criação por contrato entre particulares","dispensa de autorização legislativa","criação exclusivamente por decisão de servidor"]',0,'O art. 37, XIX, prevê lei específica para autorizar a instituição de empresa pública, sociedade de economia mista e fundação, observadas as regras constitucionais.','CF/88, art. 37, XIX; PDF de Administração Pública.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-37','1','A descentralização administrativa caracteriza-se, em sentido geral, por:','a descentralizacao administrativa caracteriza se em sentido geral por','["transferência da execução ou titularidade de determinada atividade para outra pessoa, conforme o modelo jurídico adotado","mera distribuição de tarefas entre servidores do mesmo órgão","eliminação de toda pessoa jurídica","substituição de lei por regulamento","concentração de todas as competências em um único órgão"]',0,'A descentralização envolve atuação por outra pessoa jurídica ou por particulares, conforme a forma legal adotada.','PDF de Administração Pública, organização administrativa.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-38','1','A administração direta é formada, em linhas gerais, por:','a administracao direta e formada em linhas gerais por','["órgãos que integram a estrutura das pessoas políticas","somente empresas públicas","somente sociedades de economia mista","apenas concessionárias privadas","exclusivamente autarquias"]',0,'Administração direta corresponde ao conjunto de órgãos integrantes das pessoas políticas, como União, Estados, Distrito Federal e Municípios.','PDF de Administração Pública, organização administrativa.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-39','1','Uma sociedade de economia mista integra:','uma sociedade de economia mista integra','["a Administração indireta","a Administração direta exclusivamente","o Poder Judiciário sem personalidade jurídica","somente a iniciativa privada","nenhuma estrutura administrativa"]',0,'Sociedades de economia mista são entidades da Administração indireta e possuem personalidade jurídica própria.','PDF de Administração Pública, organização administrativa.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-40','1','A publicidade de atos administrativos deve ser compreendida como:','a publicidade de atos administrativos deve ser compreendida como','["instrumento de transparência e controle, sem significar inexistência de hipóteses legais de sigilo","obrigação de divulgar qualquer informação, inclusive protegida por sigilo legal","instrumento de propaganda pessoal","faculdade exclusivamente privada","mecanismo que elimina o direito à intimidade"]',0,'Publicidade é regra de transparência, mas o ordenamento admite hipóteses de restrição de acesso quando juridicamente justificadas.','CF/88, art. 37; PDF de Administração Pública.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-41','1','Sobre os princípios administrativos, é correto afirmar que:','sobre os principios administrativos e correto afirmar que','["não há uma hierarquia abstrata que permita dizer que um princípio sempre prevalece sobre todos os demais","a eficiência sempre prevalece sobre a legalidade","a moralidade sempre elimina a publicidade","a publicidade sempre prevalece sobre qualquer outro princípio","a legalidade pode ser afastada livremente por eficiência"]',0,'O material destaca a necessidade de harmonização e ponderação conforme o caso concreto, sem prevalência apriorística de um princípio sobre os demais.','PDF de Administração Pública, princípios administrativos.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-42','1','A Emenda Constitucional nº 19/1998 é relevante para o estudo do princípio da eficiência porque:','a emenda constitucional n 19 1998 e relevante para o estudo do principio da eficiencia porque','["incluiu expressamente a eficiência entre os princípios do art. 37 da Constituição","retirou a legalidade do art. 37","criou o princípio da publicidade","eliminou a impessoalidade","substituiu a moralidade pela eficiência"]',0,'A eficiência passou a constar expressamente do caput do art. 37 com a EC 19/1998.','CF/88, art. 37; EC 19/1998; PDF de Administração Pública.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-43','1','A administração gerencial, associada ao princípio da eficiência, enfatiza especialmente:','a administracao gerencial associada ao principio da eficiencia enfatiza especialmente','["resultados, desempenho, foco no cidadão e racionalização da gestão","aumento de controles puramente formais","ausência de avaliação de resultados","centralização absoluta","desconsideração da qualidade dos serviços"]',0,'O material relaciona a eficiência ao modelo gerencial, com foco em resultados, cidadão, racionalização e avaliação.','PDF de Administração Pública, princípio da eficiência.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-2-44','1','A avaliação das políticas públicas prevista no texto constitucional reforça uma Administração orientada:','a avaliacao das politicas publicas prevista no texto constitucional reforca uma administracao orientada','["à análise de resultados e efetividade das políticas","exclusivamente ao controle formal de documentos","à promoção pessoal de gestores","à ausência de transparência","à eliminação de indicadores"]',0,'O material menciona o art. 37, § 16, como reforço do foco da Administração em resultados e efetividade das políticas públicas.','CF/88, art. 37, § 16; EC 109/2021; PDF de Administração Pública.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-3-1','1','O princípio da impessoalidade busca evitar que a atuação administrativa seja orientada por','o principio da impessoalidade busca evitar que a atuacao administrativa seja orientada por','["interesse público","critérios objetivos","favorecimento pessoal ou perseguição","procedimentos padronizados"]',2,'A impessoalidade exige atuação sem privilégios ou perseguições pessoais.','CF/88, art. 37; material-base fornecido (Fundamentos da Administração Pública).',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
