INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-4-2','1','A publicidade administrativa é absoluta, sem qualquer possibilidade de sigilo?','a publicidade administrativa e absoluta sem qualquer possibilidade de sigilo','["sim, porque todo dado estatal deve ser público","não; existem hipóteses legais de restrição de acesso","sim, exceto em processos judiciais","não, porque a publicidade não é princípio constitucional"]',1,'A publicidade é regra de transparência, mas convive com sigilos e restrições legalmente previstos.','CF/88, art. 5º, XXXIII; art. 37, caput; Lei 12.527/2011.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
