INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-5-1','1','O princípio da eficiência exige que a Administração busque','o principio da eficiencia exige que a administracao busque','["resultados adequados com uso racional dos recursos","apenas velocidade","redução de controles","atendimento de interesses particulares","dispensa de planejamento"]',0,'Eficiência envolve boa utilização dos recursos e busca de resultados adequados ao interesse público.','CF/88, art. 37; material-base fornecido (Fundamentos da Administração Pública).',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-5-2','1','Um setor reduz o tempo médio de atendimento sem perder qualidade e sem descumprir normas. Essa conduta concretiza principalmente:','um setor reduz o tempo medio de atendimento sem perder qualidade e sem descumprir normas essa conduta concretiza principalmente','["eficiência","sigilo","especialidade","tutela"]',0,'Eficiência envolve melhores resultados, qualidade e uso racional de recursos, respeitados os demais princípios.','CF/88, art. 37, caput.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-5-3','1','A eficiência administrativa deve ser avaliada apenas pela rapidez do serviço?','a eficiencia administrativa deve ser avaliada apenas pela rapidez do servico','["sim, rapidez é o único critério","não; envolve também qualidade, resultados e uso racional de recursos","sim, desde que haja economia","não, porque eficiência se aplica apenas ao setor privado"]',1,'Eficiência não se resume à velocidade; considera desempenho, qualidade e racionalidade administrativa.','CF/88, art. 37, caput.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-5-4','1','Uma medida é muito barata, mas produz serviço de baixa qualidade e retrabalho constante. Sob a ótica da eficiência:','uma medida e muito barata mas produz servico de baixa qualidade e retrabalho constante sob a otica da eficiencia','["é eficiente porque custa menos","não é necessariamente eficiente, pois custo deve ser relacionado a resultado e qualidade","é eficiente se for rápida","eficiência não considera resultados"]',1,'Economia isolada não basta; eficiência exige resultado adequado com uso racional dos recursos.','CF/88, art. 37, caput.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-6-1','1','A moralidade administrativa exige que a conduta do agente público observe','a moralidade administrativa exige que a conduta do agente publico observe','["padrões éticos compatíveis com a função pública","somente sua conveniência pessoal","apenas ordens verbais","somente critérios financeiros","exclusivamente opiniões dos usuários"]',0,'A moralidade integra os princípios constitucionais da Administração Pública.','CF/88, art. 37; material-base fornecido (Fundamentos da Administração Pública).',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-6-2','1','Um ato pode ser formalmente compatível com uma regra e ainda assim afrontar a moralidade administrativa?','um ato pode ser formalmente compativel com uma regra e ainda assim afrontar a moralidade administrativa','["não, legalidade e moralidade são idênticas","sim, porque moralidade possui conteúdo jurídico próprio ligado à ética pública e boa-fé","não, moralidade é apenas opinião pessoal","sim, mas apenas em contratos privados"]',1,'A moralidade administrativa é princípio jurídico autônomo e não se reduz ao cumprimento formal de regras.','CF/88, art. 37, caput.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-6-3','1','Servidor utiliza informação obtida no cargo para favorecer negócio particular de familiar. A situação é incompatível especialmente com:','servidor utiliza informacao obtida no cargo para favorecer negocio particular de familiar a situacao e incompativel especialmente com','["moralidade e impessoalidade","publicidade e continuidade","especialidade e desconcentração","eficiência apenas"]',0,'O uso privado da função pública e o favorecimento pessoal afrontam a ética administrativa e a neutralidade da atuação estatal.','CF/88, art. 37, caput.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-6-4','1','A moralidade administrativa deve ser entendida como:','a moralidade administrativa deve ser entendida como','["moral pessoal de cada gestor","padrão jurídico de conduta ética compatível com a função pública","mera recomendação sem efeitos jurídicos","princípio aplicável apenas a licitações"]',1,'Moralidade administrativa possui natureza jurídica e orienta a validade e legitimidade da atuação pública.','CF/88, art. 37, caput.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
