INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-8-4','1','A impessoalidade impede que a Administração considere diferenças entre situações juridicamente distintas?','a impessoalidade impede que a administracao considere diferencas entre situacoes juridicamente distintas','["sim, todos devem receber tratamento idêntico em qualquer hipótese","não; diferenças podem ser consideradas quando houver fundamento jurídico objetivo","sim, salvo autorização verbal","não, porque impessoalidade significa ausência de regras"]',1,'Impessoalidade não exige tratamento cego e idêntico, mas veda discriminações arbitrárias e favorecimentos pessoais.','CF/88, arts. 5º, caput, e 37, caput.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-9-1','1','A organização administrativa municipal tem como finalidade básica','a organizacao administrativa municipal tem como finalidade basica','["estruturar órgãos e competências para o funcionamento da Administração","substituir todas as leis por manuais","eliminar controles","permitir decisões sem competência definida"]',0,'A estrutura administrativa distribui órgãos, atribuições e responsabilidades.','CF/88, art. 37; material-base fornecido (Fundamentos da Administração Pública).',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-9-2','1','A organização administrativa distribui competências principalmente para:','a organizacao administrativa distribui competencias principalmente para','["definir responsabilidades e permitir funcionamento coordenado da Administração","eliminar controles internos","dispensar regras de competência","permitir que qualquer órgão pratique qualquer ato"]',0,'A estrutura administrativa organiza órgãos, atribuições, fluxos e responsabilidades.','Organização administrativa; material-base fornecido.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-9-3','1','Um órgão público possui personalidade jurídica própria distinta do ente ao qual pertence?','um orgao publico possui personalidade juridica propria distinta do ente ao qual pertence','["sim, sempre","não; órgão é centro de competências sem personalidade jurídica própria","sim, quando possui orçamento","sim, quando possui chefia"]',1,'Órgãos integram a estrutura da pessoa jurídica e não se confundem com entidades administrativas.','Organização administrativa; material-base fornecido.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-9-4','1','A criação de uma autarquia exige, segundo a Constituição:','a criacao de uma autarquia exige segundo a constituicao','["lei específica","portaria do secretário","decreto autônomo em qualquer caso","contrato administrativo"]',0,'A Constituição estabelece que autarquia é criada por lei específica.','CF/88, art. 37, XIX.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-10-1','1','Se um servidor recebe uma solicitação que depende de competência de outro setor, uma conduta administrativa adequada é','se um servidor recebe uma solicitacao que depende de competencia de outro setor uma conduta administrativa adequada e','["encaminhá-la ao setor competente, seguindo o fluxo institucional","resolver sem verificar competência","ignorar a solicitação","entregar a terceiros externos sem registro"]',0,'Respeitar competências e fluxos reduz erros e concretiza organização administrativa.','CF/88, art. 37; material-base fornecido (Fundamentos da Administração Pública).',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-10-2','1','Um servidor identifica que não possui competência para decidir determinado requerimento. A providência adequada é:','um servidor identifica que nao possui competencia para decidir determinado requerimento a providencia adequada e','["decidir mesmo assim para ganhar tempo","encaminhar à autoridade ou setor competente, conforme o procedimento","arquivar sem registro","pedir ao interessado que escolha quem decidirá"]',1,'Competência administrativa deve ser respeitada; o fluxo correto evita vício e assegura regularidade do processo.','Princípio da legalidade e regras de competência; material-base fornecido.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-10-3','1','A competência administrativa pode ser exercida livremente por qualquer servidor do mesmo órgão?','a competencia administrativa pode ser exercida livremente por qualquer servidor do mesmo orgao','["sim, desde que conheça o assunto","não; deve ser exercida por quem tenha atribuição jurídica para o ato","sim, se houver urgência","sim, quando o interessado concordar"]',1,'Competência é elemento jurídico da atuação administrativa e não decorre apenas de conhecimento técnico ou conveniência.','Princípio da legalidade; organização administrativa; material-base fornecido.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-10-4','1','O respeito aos fluxos e competências internas contribui especialmente para:','o respeito aos fluxos e competencias internas contribui especialmente para','["legalidade, organização e segurança das decisões","eliminação da responsabilidade funcional","dispensa de registros","liberdade absoluta do agente"]',0,'A observância das competências reduz vícios, melhora a rastreabilidade e organiza a atuação administrativa.','CF/88, art. 37, caput; organização administrativa.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-1','1','No regime jurídico-administrativo, a supremacia do interesse público indica que:','no regime juridico administrativo a supremacia do interesse publico indica que','["o interesse público pode prevalecer sobre interesses particulares dentro dos limites jurídicos","todo interesse particular deve ser ignorado pela Administração","a Administração pode agir sem lei quando invocar interesse público","o interesse público sempre elimina direitos fundamentais","o agente público pode escolher livremente o que considera interesse público"]',0,'A supremacia fundamenta prerrogativas administrativas voltadas ao interesse coletivo, sempre submetidas ao ordenamento jurídico.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-2','1','A indisponibilidade do interesse público significa que o agente público:','a indisponibilidade do interesse publico significa que o agente publico','["não pode tratar o interesse público como se fosse patrimônio pessoal","pode renunciar livremente a direitos públicos","pode negociar qualquer bem público sem autorização","deve sempre privilegiar interesses privados","pode afastar a lei para obter maior eficiência"]',0,'Os bens e interesses públicos pertencem à coletividade; o administrador exerce função pública e não pode deles dispor livremente.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-3','1','A autotutela permite que a Administração:','a autotutela permite que a administracao','["anule atos ilegais e revogue atos válidos por conveniência e oportunidade","controle exclusivamente os atos do Poder Judiciário","anule apenas atos favoráveis ao particular","revogue atos ilegais, mas nunca os anule","exerça controle somente mediante decisão judicial"]',0,'A autotutela compreende o poder-dever de controlar os próprios atos, observando legalidade e mérito administrativo.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-4','1','A tutela administrativa diferencia-se da autotutela porque a tutela:','a tutela administrativa diferencia se da autotutela porque a tutela','["envolve controle da Administração Direta sobre entidades da Administração Indireta","permite ao órgão superior revogar qualquer ato do Judiciário","é o controle que a Administração exerce sobre seus próprios atos","dispensa previsão legal","é sinônimo de poder disciplinar"]',0,'Tutela é controle finalístico; autotutela é o controle da própria Administração sobre seus atos.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-5','1','O princípio da finalidade exige que o agente público:','o principio da finalidade exige que o agente publico','["utilize a competência para atingir a finalidade prevista pelo ordenamento","use a competência para promover sua imagem","busque sempre a finalidade pessoal do governante","possa alterar a finalidade legal por conveniência","ignore a finalidade se o resultado for popular"]',0,'A competência administrativa é instrumento para alcançar a finalidade pública definida pela norma.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-6','1','O desvio de finalidade ocorre quando:','o desvio de finalidade ocorre quando','["o agente usa uma competência legal para alcançar finalidade diversa da prevista","o ato administrativo é publicado em diário oficial","a Administração age com eficiência","o particular apresenta recurso administrativo","um órgão exerce competência regularmente"]',0,'O desvio de finalidade é vício relacionado à finalidade do ato administrativo.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-7','1','O princípio da motivação está relacionado à necessidade de:','o principio da motivacao esta relacionado a necessidade de','["indicar os fundamentos de fato e de direito que justificam a decisão administrativa","publicar todas as decisões em redes sociais","obter autorização judicial para todo ato","substituir a lei por justificativas pessoais","dispensar a indicação dos fatos"]',0,'A motivação permite compreender as razões que sustentam a decisão e favorece o controle da atividade administrativa.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-8','1','O princípio da razoabilidade busca evitar decisões administrativas:','o principio da razoabilidade busca evitar decisoes administrativas','["excessivas ou inadequadas em relação à finalidade pretendida","sempre discricionárias","sempre vinculadas","publicadas oficialmente","baseadas em lei"]',0,'Razoabilidade exige coerência entre meios utilizados, circunstâncias e finalidade pública.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-9','1','A proporcionalidade exige, em linhas gerais, que a medida administrativa:','a proporcionalidade exige em linhas gerais que a medida administrativa','["seja adequada, necessária e equilibrada em relação ao objetivo buscado","seja sempre a mais severa possível","seja sempre a menos onerosa, mesmo que ineficaz","dispense análise do caso concreto","seja escolhida pelo particular"]',0,'A proporcionalidade limita excessos e exige relação equilibrada entre meio e fim.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-10','1','A segurança jurídica, como princípio administrativo, busca:','a seguranca juridica como principio administrativo busca','["estabilidade, previsibilidade e proteção da confiança nas relações jurídicas","permitir mudanças arbitrárias de entendimento","impedir qualquer alteração legislativa","eliminar o controle dos atos administrativos","garantir que todo ato seja irrevogável"]',0,'A segurança jurídica protege a confiança legítima e a previsibilidade da atuação estatal.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-11','1','O princípio da continuidade está especialmente relacionado à ideia de que:','o principio da continuidade esta especialmente relacionado a ideia de que','["a prestação dos serviços públicos deve ser mantida de forma regular, ressalvadas hipóteses juridicamente admitidas","todo serviço público jamais pode sofrer qualquer interrupção","servidores nunca podem exercer greve","qualquer paralisação é crime","serviços públicos dependem apenas da vontade do agente"]',0,'A continuidade é importante para a prestação regular dos serviços, mas não é absoluta.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-12','1','O princípio da especialidade relaciona-se à:','o principio da especialidade relaciona se a','["atuação da entidade administrativa dentro da finalidade específica para a qual foi criada","possibilidade de qualquer órgão atuar em qualquer matéria","liberdade absoluta das autarquias","eliminação da descentralização","substituição da lei por regulamento"]',0,'A especialidade limita a atuação da entidade às finalidades que justificaram sua criação.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-13','1','A presunção de legitimidade dos atos administrativos significa que eles:','a presuncao de legitimidade dos atos administrativos significa que eles','["são presumidos conformes ao Direito até que prova ou decisão em contrário demonstre o vício","são sempre absolutamente legais","não podem ser questionados","dependem sempre de homologação judicial","não produzem efeitos até prova de validade"]',0,'A presunção é relativa, admitindo prova em contrário.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-14','1','A presunção de veracidade dos atos administrativos refere-se à presunção de que:','a presuncao de veracidade dos atos administrativos refere se a presuncao de que','["os fatos declarados pela Administração são verdadeiros até prova em contrário","todo ato é moralmente correto","toda decisão é definitiva","todo ato é discricionário","a lei foi corretamente elaborada"]',0,'Veracidade diz respeito aos fatos; legitimidade, à conformidade jurídica.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-15','1','A impessoalidade na Administração Pública impede:','a impessoalidade na administracao publica impede','["promoção pessoal de autoridades ou servidores em atos, programas e obras públicas","qualquer atendimento individualizado ao cidadão","a existência de órgãos públicos","a publicação de atos administrativos","a prestação de serviços públicos"]',0,'A atuação administrativa deve visar ao interesse público, sem favorecimento ou promoção pessoal.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-16','1','A moralidade administrativa exige:','a moralidade administrativa exige','["conduta ética e compatível com padrões jurídicos e de boa administração","apenas cumprimento literal de qualquer regra","liberdade absoluta para o agente","sigilo de todos os atos públicos","ausência de motivação"]',0,'Moralidade é princípio jurídico e não se reduz à moral pessoal do agente.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-17','1','A publicidade administrativa tem como uma de suas funções:','a publicidade administrativa tem como uma de suas funcoes','["dar transparência aos atos públicos e permitir controle social, ressalvadas hipóteses legais de sigilo","tornar todos os dados pessoais públicos","substituir a motivação dos atos","impedir o acesso a processos administrativos","garantir promoção pessoal do gestor"]',0,'Publicidade favorece transparência e controle, sem afastar as hipóteses legais de restrição de acesso.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-18','1','O princípio da eficiência orienta a Administração a:','o principio da eficiencia orienta a administracao a','["buscar bons resultados com uso adequado e racional dos recursos públicos","priorizar velocidade mesmo contra a lei","reduzir custos a qualquer preço","eliminar controles administrativos","atender somente às demandas mais simples"]',0,'Eficiência envolve qualidade, produtividade e racionalidade na utilização dos recursos.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-19','1','A Constituição Federal, no art. 37, caput, estabelece expressamente os princípios:','a constituicao federal no art 37 caput estabelece expressamente os principios','["legalidade, impessoalidade, moralidade, publicidade e eficiência","legalidade, supremacia, autotutela, continuidade e eficiência","moralidade, finalidade, especialidade, publicidade e motivação","legalidade, hierarquia, disciplina, publicidade e eficiência","impessoalidade, tutela, autotutela, moralidade e continuidade"]',0,'O caput do art. 37 apresenta o conjunto conhecido pela sigla LIMPE.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-20','1','O princípio da legalidade aplicado ao agente público significa que:','o principio da legalidade aplicado ao agente publico significa que','["a atuação administrativa depende de autorização ou determinação do ordenamento jurídico","o agente pode fazer tudo que a lei não proíba","a Administração pode agir contra a lei para obter eficiência","a vontade pessoal prevalece sobre a norma","somente atos judiciais precisam observar a lei"]',0,'Para a Administração, a legalidade é vinculante: o agente atua nos limites estabelecidos pelo Direito.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-21','1','A diferença básica entre a legalidade para particulares e para a Administração é que:','a diferenca basica entre a legalidade para particulares e para a administracao e que','["o particular pode fazer o que a lei não proíbe, enquanto a Administração atua conforme autorização ou determinação jurídica","ambos só podem fazer aquilo que uma lei específica determinar","a Administração não precisa observar a Constituição","o particular depende sempre de autorização administrativa","a Administração possui liberdade maior que o particular"]',0,'Essa distinção é destacada no material como característica da atuação administrativa.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-22','1','A isonomia, no âmbito administrativo, está ligada à ideia de:','a isonomia no ambito administrativo esta ligada a ideia de','["tratar situações equivalentes sem discriminações arbitrárias","tratar todos de maneira absolutamente idêntica em qualquer circunstância","favorecer quem possui maior influência","eliminar critérios objetivos de seleção","dispensar concursos públicos"]',0,'Isonomia exige igualdade de tratamento juridicamente justificável.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-23','1','A razoabilidade e a proporcionalidade funcionam como limites especialmente importantes:','a razoabilidade e a proporcionalidade funcionam como limites especialmente importantes','["ao exercício do poder discricionário","à existência de leis","à publicação dos atos","ao funcionamento do Poder Legislativo","à autonomia dos particulares"]',0,'Esses princípios ajudam a impedir escolhas administrativas arbitrárias ou excessivas.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-24','1','Segundo a Súmula Vinculante 13, a vedação ao nepotismo está relacionada principalmente aos princípios da:','segundo a sumula vinculante 13 a vedacao ao nepotismo esta relacionada principalmente aos principios da','["impessoalidade e moralidade","publicidade e continuidade","eficiência e especialidade","legalidade e hierarquia apenas","publicidade e autotutela"]',0,'A vedação ao nepotismo concretiza, entre outros, os princípios da impessoalidade e moralidade.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-25','1','A Administração Direta é composta, em sentido administrativo, por:','a administracao direta e composta em sentido administrativo por','["órgãos integrados às pessoas políticas, como União, Estados, Distrito Federal e Municípios","somente autarquias e fundações públicas","empresas públicas e sociedades de economia mista","apenas empresas privadas contratadas pelo Estado","somente entidades com personalidade jurídica própria"]',0,'A Administração Direta é formada pelos órgãos das pessoas políticas.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-26','1','A Administração Indireta compreende entidades como:','a administracao indireta compreende entidades como','["autarquias, fundações públicas, empresas públicas e sociedades de economia mista","ministérios e secretarias exclusivamente","câmaras municipais e tribunais apenas","partidos políticos e sindicatos","órgãos sem personalidade jurídica"]',0,'São entidades dotadas de personalidade jurídica própria, criadas ou autorizadas na forma constitucional e legal.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-27','1','A desconcentração administrativa ocorre quando:','a desconcentracao administrativa ocorre quando','["competências são distribuídas internamente dentro da mesma pessoa jurídica, mediante criação ou organização de órgãos","uma pessoa jurídica transfere a execução a outra pessoa jurídica","um serviço é privatizado","um órgão passa a integrar outro Poder","um particular recebe patrimônio público definitivamente"]',0,'Desconcentração é distribuição interna de competências, sem criação de nova pessoa jurídica.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-28','1','A descentralização administrativa caracteriza-se, em regra, pela:','a descentralizacao administrativa caracteriza se em regra pela','["transferência de determinada atividade ou execução para outra pessoa jurídica ou para particular, conforme o modelo jurídico","simples divisão interna de tarefas dentro do mesmo órgão","criação de setores dentro de uma secretaria","substituição de servidores efetivos","eliminação da personalidade jurídica"]',0,'Na descentralização há atuação de outra pessoa, distinguindo-se da desconcentração.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-29','1','Uma autarquia é, em regra:','uma autarquia e em regra','["pessoa jurídica de direito público criada por lei para desempenhar atividade administrativa típica do Estado","órgão sem personalidade jurídica","empresa privada contratada pelo Estado","sociedade empresária de capital exclusivamente privado","entidade criada apenas por contrato"]',0,'Autarquias integram a Administração Indireta e possuem personalidade jurídica de direito público.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-30','1','A empresa pública caracteriza-se, em regra, por ser:','a empresa publica caracteriza se em regra por ser','["pessoa jurídica de direito privado com capital exclusivamente público","órgão sem personalidade jurídica","pessoa jurídica de direito público com capital privado","sociedade necessariamente formada por capital público e privado","entidade sem finalidade administrativa"]',0,'Empresa pública possui personalidade de direito privado e capital integralmente público.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-31','1','A sociedade de economia mista caracteriza-se por:','a sociedade de economia mista caracteriza se por','["ser pessoa jurídica de direito privado constituída sob a forma de sociedade anônima, com maioria do capital votante estatal","ter capital exclusivamente privado","ser necessariamente autarquia","não possuir personalidade jurídica","ser órgão da Administração Direta"]',0,'A sociedade de economia mista possui capital público e privado, com controle estatal, e forma de sociedade anônima.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-32','1','O controle exercido pela Administração Direta sobre uma entidade da Administração Indireta é associado ao princípio da:','o controle exercido pela administracao direta sobre uma entidade da administracao indireta e associado ao principio da','["tutela","autotutela","publicidade pessoal","hierarquia absoluta","continuidade"]',0,'A tutela é controle finalístico exercido nos limites legais sobre entidades da Administração Indireta.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-33','1','O poder-dever de corrigir os próprios atos ilegais decorre principalmente da:','o poder dever de corrigir os proprios atos ilegais decorre principalmente da','["autotutela","descentralização","especialidade","publicidade","isonomia"]',0,'A Administração deve controlar seus próprios atos e afastar aqueles que estejam eivados de ilegalidade.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-34','1','A revogação de ato administrativo válido ocorre, em regra, por razões de:','a revogacao de ato administrativo valido ocorre em regra por razoes de','["conveniência e oportunidade","ilegalidade obrigatória","incompetência do Judiciário","falta de publicação da Constituição","ausência de personalidade jurídica"]',0,'Revogação incide sobre mérito administrativo; anulação decorre de ilegalidade.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-35','1','A anulação de um ato administrativo ocorre quando se constata:','a anulacao de um ato administrativo ocorre quando se constata','["ilegalidade ou vício jurídico que comprometa sua validade","mera mudança de preferência política","conveniência administrativa","aumento de eficiência","mudança de gestão sem vício"]',0,'A anulação é medida de controle de legalidade.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-36','1','O interesse público, segundo o material, deve:','o interesse publico segundo o material deve','["orientar a atuação de pessoas, órgãos e agentes que desempenham atividades administrativas","ser substituído pelos interesses particulares dos agentes","ser considerado apenas quando houver fiscalização","ser ignorado em atividades internas","ser definido livremente por cada servidor"]',0,'A finalidade pública permeia a atuação administrativa.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-37','1','A indisponibilidade do interesse público é uma limitação ao administrador porque:','a indisponibilidade do interesse publico e uma limitacao ao administrador porque','["impede que ele trate interesses e bens públicos como se fossem próprios","permite alienar livremente patrimônio público","autoriza renunciar a direitos públicos sem base legal","dispensa prestação de contas","permite agir sem competência"]',0,'O administrador é gestor de interesses alheios e deve respeitar os limites legais.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-38','1','A publicidade não significa que:','a publicidade nao significa que','["todo e qualquer dado pessoal ou informação estatal deva ser divulgado sem restrições","os atos públicos devam ser transparentes quando não houver hipótese legal de sigilo","o cidadão possa exercer controle social","a Administração deva dar transparência à sua atuação","a divulgação possa ter exceções previstas em lei"]',0,'A publicidade convive com hipóteses legais de sigilo e proteção de informações.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-39','1','Um ato administrativo que favorece determinada pessoa por amizade pessoal, sem critério público legítimo, viola sobretudo a:','um ato administrativo que favorece determinada pessoa por amizade pessoal sem criterio publico legitimo viola sobretudo a','["impessoalidade","continuidade","especialidade","autotutela","descentralização"]',0,'O favorecimento pessoal contraria a exigência de atuação impessoal.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
