INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-41','1','A presunção de legitimidade e a presunção de veracidade dos atos administrativos são, em regra:','a presuncao de legitimidade e a presuncao de veracidade dos atos administrativos sao em regra','["relativas, admitindo prova em contrário","absolutas e irrefutáveis","inexistentes nos atos públicos","dependentes de autorização judicial","aplicáveis somente a contratos privados"]',0,'O material destaca que ambas admitem prova em sentido contrário.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-42','1','O princípio da continuidade possui relação direta com:','o principio da continuidade possui relacao direta com','["a eficiência e a supremacia do interesse público","somente a moralidade","somente a publicidade","apenas a autonomia privada","exclusivamente a descentralização"]',0,'A prestação continuada atende ao interesse público e favorece a eficiência do serviço.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-43','1','Em matéria de princípios administrativos, a finalidade pública é importante porque:','em materia de principios administrativos a finalidade publica e importante porque','["o exercício de uma competência deve estar orientado ao objetivo previsto pelo ordenamento","qualquer finalidade escolhida pelo agente é válida","a finalidade privada prevalece sobre a pública","o agente pode usar a competência para promoção pessoal","a finalidade dispensa observância da lei"]',0,'Competência administrativa não pode ser utilizada para fins estranhos àqueles previstos juridicamente.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-44','1','O princípio da especialidade é especialmente relevante para:','o principio da especialidade e especialmente relevante para','["entidades administrativas criadas para desempenhar determinadas finalidades específicas","qualquer cidadão em suas relações privadas","órgãos sem competência definida","empresas estrangeiras sem vínculo estatal","atividades exclusivamente eleitorais"]',0,'A especialidade vincula a entidade à finalidade legal de sua criação.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-45','1','Uma decisão administrativa desproporcional pode ser questionada porque:','uma decisao administrativa desproporcional pode ser questionada porque','["o meio adotado não deve impor restrição excessiva em comparação com a finalidade buscada","toda decisão administrativa é imune a controle","a eficiência elimina direitos","o interesse público nunca possui limites","a discricionariedade é ilimitada"]',0,'A proporcionalidade atua contra excessos na atuação administrativa.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-46','1','A motivação administrativa contribui para:','a motivacao administrativa contribui para','["transparência, controle e possibilidade de verificar a racionalidade da decisão","eliminação da publicidade","substituição da lei por argumentos pessoais","dispensa de controle judicial","promoção pessoal do agente"]',0,'Conhecer os fundamentos facilita o controle jurídico e administrativo.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('1-new-47','1','No contexto administrativo, a moralidade não se confunde integralmente com a legalidade porque:','no contexto administrativo a moralidade nao se confunde integralmente com a legalidade porque','["uma conduta pode exigir padrões éticos e de boa-fé que não se esgotam na simples análise formal da lei","moralidade é apenas opinião pessoal","legalidade nunca possui relação com moralidade","moralidade permite descumprir a Constituição","somente particulares estão sujeitos à moralidade"]',0,'Os princípios são relacionados, mas possuem conteúdos jurídicos distintos.','PDF Noções de Administração Pública – Prefeitura de Itajaí/SC 2026; CF/88 e legislação/jurisprudência indicadas no material.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
