INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q19','2','Com relação aos tipos de correspondências oficiais, assinale a alternativa correta em se tratando das mensagens de correio eletrônico (e-mail).','com relacao aos tipos de correspondencias oficiais assinale a alternativa correta em se tratando das mensagens de correio eletronico e mail','["A opção “Cco” refere-se à confirmação de recebimento de uma cópia da mensagem enviada pelo destinatário.","Para indicar alta prioridade, é possível utilizar um arquivo anexado.","Devido à fácil comunicação, não é necessário utilizar linguagem formal.","O correio eletrônico, por seu baixo custo e facilidade, transformou-se na principal forma de comunicação para transmissão de documentos.","Ao retornar como não entregue, a mensagem irá para a categoria spam."]',3,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',19,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020') ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
