INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('6-10-1','6','A LAI tem como orientação geral','a lai tem como orientacao geral','["ampliar o acesso a informações públicas, respeitando as exceções legais","tornar todo documento secreto","impedir controle social","dispensar transparência","proibir solicitações do cidadão"]',0,'A regra geral é o acesso, com restrições previstas em lei.','Lei 12.527/2011 (LAI) e material-base fornecido (Ética, Legislação e Transparência).',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('6-v2-41','6','Segundo a Lei de Acesso à Informação, a divulgação de informações de interesse coletivo ou geral, independentemente de pedido, corresponde à chamada:','segundo a lei de acesso a informacao a divulgacao de informacoes de interesse coletivo ou geral independentemente de pedido corresponde a chamada','["transparência ativa","transparência passiva","reserva legal","classificação automática"]',0,'A LAI determina a divulgação espontânea de informações de interesse coletivo ou geral.','Lei 12.527/2011, art. 8º.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('6-v2-42','6','Um pedido de acesso à informação de interesse público pode exigir que o cidadão apresente a razão pela qual deseja a informação?','um pedido de acesso a informacao de interesse publico pode exigir que o cidadao apresente a razao pela qual deseja a informacao','["não; não se pode exigir motivação do pedido","sim, sempre","sim, apenas em municípios","sim, se o órgão preferir"]',0,'A LAI veda exigências relativas aos motivos determinantes da solicitação de informação de interesse público.','Lei 12.527/2011, art. 10.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('6-v2-43','6','Se a informação solicitada estiver disponível, a LAI estabelece como regra que o acesso seja:','se a informacao solicitada estiver disponivel a lai estabelece como regra que o acesso seja','["imediato","sempre em 30 dias","somente após recurso","apenas mediante pagamento"]',0,'O art. 11 determina que o órgão autorize ou conceda acesso imediato à informação disponível.','Lei 12.527/2011, art. 11, caput.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('6-v2-44','6','Quando não for possível conceder acesso imediato, o prazo geral previsto na LAI para resposta é de até:','quando nao for possivel conceder acesso imediato o prazo geral previsto na lai para resposta e de ate','["20 dias","5 dias","60 dias","90 dias"]',0,'A LAI prevê prazo não superior a 20 dias, observadas as hipóteses e condições legais de prorrogação.','Lei 12.527/2011, art. 11, § 1º.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
