INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q39','6','De acordo com a Lei nº 2960/95, considera-se “carreira”:','de acordo com a lei n 2960 95 considera se carreira','["o conjunto de cargos de diferentes classes, escalonados hierarquicamente de acordo com a complexidade e afinidade das atribuições, para progressão dos titulares dos cargos que a integram.","o conjunto de cargos públicos da mesma atividade, atribuições, responsabilidades e níveis de vencimento.","o conjunto dos cargos de um mesmo órgão ou Poder.","o conjunto de tarefas e responsabilidades cometidas ao servidor público.","o vencimento acrescido das vantagens pecuniárias a que o servidor tenha direito, estabelecidas em lei."]',0,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',39,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020') ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q40','6','Assinale a alternativa correta de acordo com a Lei nº 2960/95.','assinale a alternativa correta de acordo com a lei n 2960 95','["O limite mínimo de idade para inscrições é de 21 anos completos, na data de encerramento da inscrição nos concursos públicos municipais.","É proibida a acumulação de férias, salvo por absoluta necessidade do serviço e pelo período máximo de 2 anos.","Será concedido adicional noturno correspondente a 20% do valor da hora normal, prestado entre 22 horas e 6 horas do dia seguinte.","A demissão “a bem do serviço público” incompatibiliza o ex-servidor com o serviço público municipal pelo prazo de 15 anos, enquanto a demissão simples o faz pelo prazo de 10 anos.","O servidor em débito com o erário que for demitido, ou que tiver a sua aposentadoria ou disponibilidade cassada, terá o prazo de 30 dias para quitar o débito, sob pena de inscrição em dívida ativa."]',1,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',40,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020') ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-1','7','Em “Há dois anos estudo para concursos”, a forma “há” indica:','em ha dois anos estudo para concursos a forma ha indica','["tempo passado","tempo futuro","distância futura","finalidade","comparação"]',0,'O verbo haver, nesse emprego temporal, indica tempo decorrido.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-2','7','Assinale a alternativa em que “a fim de” está empregado corretamente:','assinale a alternativa em que a fim de esta empregado corretamente','["Estudou a fim de melhorar seu desempenho.","As matérias são a fim entre si.","Ele estava afim de Direito Administrativo, no sentido de finalidade.","As disciplinas são a fim de conteúdo.","Foi aprovado afim de estudar mais."]',0,'“A fim de” equivale a “para” e expressa finalidade; “afim” é adjetivo relacionado a afinidade.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-3','7','Assinale a frase correta quanto ao emprego de “onde” e “aonde”:','assinale a frase correta quanto ao emprego de onde e aonde','["Aonde você vai depois da prova?","Aonde você mora?","Onde você pretende ir amanhã?","Aonde está o documento?","Onde quer que eu vá, retornarei ao escritório."]',0,'“Aonde” é usado com verbos que regem a preposição “a” e indicam movimento/destino.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-4','7','Em “Choveram críticas à decisão”, o verbo “chover” foi empregado em sentido:','em choveram criticas a decisao o verbo chover foi empregado em sentido','["conotativo","exclusivamente denotativo","técnico","jurídico literal","metalinguístico"]',0,'“Choveram críticas” usa linguagem figurada para indicar grande quantidade de críticas.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-5','7','Em “A saúde estava frágil”, o antônimo de “frágil” é:','em a saude estava fragil o antonimo de fragil e','["robusta","delicada","débil","sensível","vulnerável"]',0,'“Robusta” significa forte ou resistente, sendo antônimo de “frágil”.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
