INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-9','7','Em “Trabalha-se muito aqui”, o sujeito é:','em trabalha se muito aqui o sujeito e','["indeterminado","simples expresso","composto","oculto determinado","inexistente"]',0,'A construção com “se” e verbo intransitivo pode indeterminar o agente da ação.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
