INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-11','7','Em “Ele comprou um computador”, o termo “um computador” exerce função de:','em ele comprou um computador o termo um computador exerce funcao de','["objeto direto","objeto indireto","complemento nominal","adjunto adverbial","sujeito"]',0,'O verbo “comprar” é transitivo direto e recebe complemento sem preposição.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-12','7','Em “Ela gosta de música”, o termo “de música” é:','em ela gosta de musica o termo de musica e','["objeto indireto","objeto direto","sujeito","adjunto adnominal","aposto"]',0,'“Gostar” rege a preposição “de”; o termo completa o verbo como objeto indireto.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-13','7','Em “João tem dependência de café”, “de café” completa o sentido de:','em joao tem dependencia de cafe de cafe completa o sentido de','["um substantivo","um verbo","um pronome","um advérbio","uma conjunção"]',0,'“Dependência” é substantivo e “de café” funciona como complemento nominal.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-14','7','Em “Ele é dependente de café”, “de café” completa o sentido de:','em ele e dependente de cafe de cafe completa o sentido de','["um adjetivo","um verbo transitivo direto","um artigo","um pronome pessoal","um substantivo próprio"]',0,'“Dependente” é adjetivo e recebe o complemento “de café”.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
