INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-27','7','Em “Não só estudou, mas também resolveu questões”, a expressão “mas também” indica:','em nao so estudou mas tambem resolveu questoes a expressao mas tambem indica','["adição","causa","condição","conclusão","concessão"]',0,'A estrutura correlativa “não só... mas também” soma informações.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-28','7','Assinale a alternativa em que há concordância verbal adequada:','assinale a alternativa em que ha concordancia verbal adequada','["Os candidatos estudaram bastante.","Os candidato estudaram bastante.","Os candidatos estudou bastante.","A maioria dos candidato estudaram bastante, obrigatoriamente.","Os candidatos estuda bastante."]',0,'O verbo concorda com o sujeito plural “os candidatos”.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-29','7','Assinale a alternativa com concordância nominal adequada:','assinale a alternativa com concordancia nominal adequada','["As questões difíceis foram resolvidas.","As questão difícil foram resolvidas.","As questões difícil foi resolvida.","Os questão difíceis foram resolvido.","A questões difíceis foram resolvida."]',0,'Artigo, substantivo, adjetivo e verbo estão adequadamente flexionados.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-30','7','Em “O candidato respondeu rapidamente”, “rapidamente” é:','em o candidato respondeu rapidamente rapidamente e','["advérbio","adjetivo","substantivo","pronome","conjunção"]',0,'O termo modifica o verbo “respondeu”, indicando modo.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-31','7','Em “Aquela questão foi anulada”, “aquela” é:','em aquela questao foi anulada aquela e','["pronome demonstrativo","artigo definido","advérbio","conjunção","substantivo"]',0,'“Aquela” é pronome demonstrativo, pois localiza o referente no espaço, tempo ou discurso.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-32','7','Em “Dois candidatos chegaram cedo”, “dois” é:','em dois candidatos chegaram cedo dois e','["numeral","artigo","pronome pessoal","advérbio","preposição"]',0,'“Dois” indica quantidade determinada.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-33','7','Em “O servidor entregou o documento ao chefe”, “ao chefe” exerce função de:','em o servidor entregou o documento ao chefe ao chefe exerce funcao de','["objeto indireto","objeto direto","sujeito","predicativo","vocativo"]',0,'O verbo “entregar” admite destinatário introduzido por preposição.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-34','7','Em “A aprovação do candidato surpreendeu a equipe”, “do candidato” relaciona-se ao substantivo “aprovação” e exerce função de:','em a aprovacao do candidato surpreendeu a equipe do candidato relaciona se ao substantivo aprovacao e exerce funcao de','["complemento nominal","objeto direto","objeto indireto","vocativo","predicado"]',0,'O termo preposicionado completa o sentido do substantivo “aprovação”.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-35','7','Em “Pedro, revise suas anotações”, a expressão “Pedro” é:','em pedro revise suas anotacoes a expressao pedro e','["vocativo","sujeito","objeto direto","aposto","adjunto adverbial"]',0,'O vocativo é usado para chamar ou interpelar alguém.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-36','7','Em “Itajaí, importante município catarinense, possui atividade portuária”, o trecho “importante município catarinense” é:','em itajai importante municipio catarinense possui atividade portuaria o trecho importante municipio catarinense e','["aposto","vocativo","objeto direto","predicativo do objeto","adjunto adverbial"]',0,'O trecho explica ou especifica o termo “Itajaí”, funcionando como aposto.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-37','7','Em “O relatório, que foi revisado ontem, está pronto”, a oração “que foi revisado ontem” é:','em o relatorio que foi revisado ontem esta pronto a oracao que foi revisado ontem e','["oração subordinada adjetiva explicativa","oração coordenada conclusiva","oração subordinada adverbial causal","oração principal","oração subordinada substantiva"]',0,'A oração caracteriza “relatório” e aparece isolada por vírgulas, com valor explicativo.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-38','7','Em “Quando terminar a prova, revise as respostas”, a oração iniciada por “quando” expressa:','em quando terminar a prova revise as respostas a oracao iniciada por quando expressa','["tempo","causa","concessão","finalidade","comparação"]',0,'“Quando” introduz circunstância temporal.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-39','7','Em “O servidor estudou para que pudesse melhorar”, “para que” introduz ideia de:','em o servidor estudou para que pudesse melhorar para que introduz ideia de','["finalidade","causa","oposição","conclusão","condição"]',0,'A locução “para que” apresenta o objetivo da ação principal.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-40','7','A interpretação textual em concursos exige, entre outros cuidados:','a interpretacao textual em concursos exige entre outros cuidados','["distinguir informações explicitamente apresentadas de inferências que podem ser legitimamente extraídas do texto","considerar verdadeira qualquer informação que pareça plausível","ignorar conectivos","substituir o texto pela opinião do candidato","interpretar todas as palavras em sentido figurado"]',0,'Compreensão exige atenção ao que o texto efetivamente permite concluir, sem extrapolações indevidas.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-41','7','Em uma questão de interpretação, uma inferência válida deve:','em uma questao de interpretacao uma inferencia valida deve','["decorrer logicamente de informações presentes no texto","ser baseada exclusivamente em conhecimento pessoal","contradizer o texto quando parecer mais provável","ignorar o contexto","depender apenas do título"]',0,'Inferência é conclusão autorizada pelas informações e relações apresentadas no texto.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-42','7','A palavra “afim”, quando usada como adjetivo, significa:','a palavra afim quando usada como adjetivo significa','["semelhante ou relacionado","com finalidade de","em direção a","depois de","por causa de"]',0,'“Afim” é adjetivo e indica afinidade ou semelhança.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-43','7','Em “O candidato está a fim de estudar”, a expressão “a fim de” indica:','em o candidato esta a fim de estudar a expressao a fim de indica','["finalidade","afinidade","oposição","conclusão","tempo"]',0,'A expressão equivale a “para”.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-44','7','Em “O documento está onde você deixou”, “onde” indica:','em o documento esta onde voce deixou onde indica','["localização","direção necessariamente futura","causa","finalidade","concessão"]',0,'“Onde” é empregado para indicar lugar, especialmente com valor estático.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-45','7','A função principal da pontuação em um texto é:','a funcao principal da pontuacao em um texto e','["organizar a estrutura sintática e orientar a leitura e os sentidos","substituir todas as conjunções","determinar sempre a pronúncia das palavras","eliminar ambiguidades em qualquer situação automaticamente","indicar apenas pausas respiratórias"]',0,'A pontuação contribui para estrutura, ritmo, relações sintáticas e interpretação.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-new-46','7','A vírgula pode ser usada para:','a virgula pode ser usada para','["isolar vocativo, aposto explicativo e determinadas orações ou termos deslocados","separar obrigatoriamente sujeito e verbo em qualquer frase","substituir qualquer ponto final","separar verbo de seu complemento direto sempre","indicar exclusivamente uma pausa de respiração"]',0,'A vírgula possui funções sintáticas e discursivas específicas; não deve separar arbitrariamente sujeito e predicado.','PDF Língua Portuguesa – Prefeitura de Itajaí/SC 2026 (Pós-Edital), especialmente os tópicos de ortografia, morfologia, sintaxe, semântica e interpretação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-v3-01','7','Assinale a alternativa em que o uso da crase está correto:','assinale a alternativa em que o uso da crase esta correto','["O servidor dirigiu-se à chefia para esclarecer a dúvida.","O relatório foi entregue à partir das oito horas.","A reunião ocorrerá de segunda à sexta.","O documento foi enviado à todos os setores."]',0,'Há fusão da preposição exigida por ''dirigir-se a'' com o artigo feminino de ''a chefia''.','Língua Portuguesa — regência e crase.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-v3-02','7','Em ''Os documentos que chegaram ontem serão analisados hoje'', a oração ''que chegaram ontem'' é:','em os documentos que chegaram ontem serao analisados hoje a oracao que chegaram ontem e','["subordinada adjetiva restritiva","subordinada adjetiva explicativa","subordinada substantiva subjetiva","coordenada sindética explicativa"]',0,'Sem vírgulas, a oração restringe o conjunto de documentos aos que chegaram ontem.','Língua Portuguesa — período composto.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-v3-03','7','Assinale a frase com concordância verbal correta:','assinale a frase com concordancia verbal correta','["Fazem dois anos que o sistema foi implantado.","Houveram muitos pedidos ontem.","Existe diversos processos pendentes.","Devem existir soluções para o problema."]',3,'O verbo ''existir'' concorda com o sujeito ''soluções''; já ''fazer'' indicando tempo e ''haver'' no sentido de existir são impessoais.','Língua Portuguesa — concordância verbal.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-v3-04','7','Na frase ''Embora estivesse cansado, o servidor concluiu o relatório'', a conjunção ''embora'' expressa ideia de:','na frase embora estivesse cansado o servidor concluiu o relatorio a conjuncao embora expressa ideia de','["causa","concessão","condição","conclusão"]',1,'A oração concessiva apresenta um fato que poderia dificultar, mas não impede a ocorrência da ação principal.','Língua Portuguesa — relações semânticas entre orações.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-v3-05','7','Assinale a alternativa em que a colocação pronominal está de acordo com a norma-padrão:','assinale a alternativa em que a colocacao pronominal esta de acordo com a norma padrao','["Não me informaram o número do processo.","Me não informaram o número do processo.","Jamais informaram-me o número do processo.","Quem entregou-me o documento?"]',0,'Palavras negativas atraem o pronome átono, exigindo próclise.','Língua Portuguesa — colocação pronominal.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-v3-06','7','Em ''O chefe solicitou que o servidor revisasse o ofício'', o termo ''que o servidor revisasse o ofício'' exerce função de:','em o chefe solicitou que o servidor revisasse o oficio o termo que o servidor revisasse o oficio exerce funcao de','["oração subordinada substantiva objetiva direta","oração subordinada adverbial causal","oração subordinada adjetiva restritiva","oração coordenada adversativa"]',0,'A oração completa o sentido do verbo transitivo direto ''solicitou''.','Língua Portuguesa — sintaxe do período composto.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-v3-07','7','Assinale a alternativa em que a pontuação está adequada:','assinale a alternativa em que a pontuacao esta adequada','["Senhores servidores, encaminhem os relatórios até amanhã.","Senhores, servidores encaminhem os relatórios até amanhã.","Senhores servidores encaminhem, os relatórios até amanhã.","Senhores servidores encaminhem os relatórios, até amanhã."]',0,'O vocativo ''Senhores servidores'' deve ser isolado por vírgula.','Língua Portuguesa — pontuação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-v3-08','7','Na frase ''O processo foi arquivado porque o prazo havia terminado'', a oração introduzida por ''porque'' expressa:','na frase o processo foi arquivado porque o prazo havia terminado a oracao introduzida por porque expressa','["causa","consequência","comparação","finalidade"]',0,'A oração explica a razão do arquivamento.','Língua Portuguesa — relações semânticas.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-v3-09','7','Assinale a opção em que há sentido denotativo:','assinale a opcao em que ha sentido denotativo','["A notícia caiu como uma bomba.","O servidor abriu a porta da sala.","A chefia engoliu a reclamação.","O prazo voou."]',1,'O verbo ''abrir'' e o substantivo ''porta'' são empregados em sentido literal.','Língua Portuguesa — denotação e conotação.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('7-v3-10','7','Em ''Precisam-se de servidores experientes'', a construção está:','em precisam se de servidores experientes a construcao esta','["incorreta; o correto é ''Precisa-se de servidores experientes''","correta, pois o verbo concorda com ''servidores''","correta apenas na linguagem informal","incorreta; o correto é ''Precisam de-se servidores experientes''"]',0,'Com verbo transitivo indireto acompanhado de índice de indeterminação do sujeito, o verbo permanece na 3ª pessoa do singular.','Língua Portuguesa — concordância e partícula ''se''.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
