INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q04','7','Considere a frase adaptada do texto e assinale a alternativa correta.','considere a frase adaptada do texto e assinale a alternativa correta','["Contém problemas com a coesão textual na articulação das ideias.","“… a informação” é um termo essencial na frase; é, pois um sujeito simples.","Se trocássemos o termo sublinhado por “os quais” ele concordaria com “outros” e a frase continuaria correta.","A frase “embora o que lhe pedimos é uma espécie de loucura mansa” dá uma ideia aditiva à frase no seu contexto.","A palavra “não” que inicia o texto tem função sintática diferente das duas outras vezes em que aparece, já que se refere a um verbo enquanto que as outras a um adjetivo."]',0,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',4,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020') ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q05','7','Sobre a frase “Crônica tem esta vantagem”, assinale a alternativa que apresenta a correta análise morfológica.','sobre a frase cronica tem esta vantagem assinale a alternativa que apresenta a correta analise morfologica','["adjetivo, verbo, pronome possessivo, adjetivo","nome próprio, nome de ação, preposição, adjetivo","substantivo próprio, verbo conjugado, pronome demonstrativo, substantivo","substantivo, verbo, pronome possessivo, adjetivo","substantivo, verbo, pronome demonstrativo, substantivo"]',4,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',5,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020') ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('fepese-itajai-2020-vm1-q06','7','Assinale a alternativa em que a estruturação frasal (colocada entre parênteses) não alterou o sentido da primeira frase, considerando o texto posto no início da prova.','assinale a alternativa em que a estruturacao frasal colocada entre parenteses nao alterou o sentido da primeira frase considerando o texto posto no inicio da prova','["Ele sabe que seu prazo de atuação é limitado. (Que é limitado seu prazo de atuação ele sabe.)","Não se exige do cronista geral a informação. (Do cronista não se exige a informação geral.)","Não exige de quem a faz o nervosismo saltitante do repórter. (O saltitante nervosismo de quem a faz não exige do repórter.)","Forçado a definir uma posição correta diante dos grandes problemas. (Uma posição correta diante dos corretos grandes problemas, é forçado a decidir.)","Desperte em nós a inclinação para o jogo da fantasia. (A inclinação, em nós, desperte para o jogo da fantasia.)"]',0,'Gabarito definitivo FEPESE 2020.','Prova oficial FEPESE - Prefeitura de Itajaí/SC - 2020',2,1,'prova-oficial','FEPESE','Prefeitura de Itajaí/SC',2020,'Agente em Atividades Administrativas',6,'https://www.pciconcursos.com.br/provas/download/agente-em-atividades-administrativas-prefeitura-itajai-sc-fepese-2020') ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
