INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('legacy-pt-005','7','Substituindo o termo sublinhado por um pronome: ''Vou entregar o presente'', teremos:','substituindo o termo sublinhado por um pronome vou entregar o presente teremos','["Entregar-lhe","Entregar-te","Entregar-o","Entregá-lo","Entregar-me"]',3,'Quando o verbo termina em ''r'', ''s'' ou ''z'', retira-se a terminação e o pronome ''o/a'' vira ''lo/la''.','Banco legado perguntas.json',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('legacy-pt-006','7','Qual frase abaixo possui um pronome de tratamento adequado para autoridades?','qual frase abaixo possui um pronome de tratamento adequado para autoridades','["Você quer café?","Vossa Excelência virá?","Tu queres ir?","A gente vai amanhã","Vossa Senhoria é meu amigo"]',1,'''Vossa Excelência'' é o pronome de tratamento utilizado para altas autoridades, como juízes e políticos.','Banco legado perguntas.json',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('legacy-pt-007','7','Assinale a alternativa com um pronome indefinido:','assinale a alternativa com um pronome indefinido','["Aquele","Alguém","Teu","Nós","Esta"]',1,'''Alguém'' é um pronome indefinido pois se refere à terceira pessoa de modo vago ou impreciso.','Banco legado perguntas.json',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('legacy-pt-008','7','Na oração ''Os moradores de Itajaí amam o porto'', qual é o sujeito?','na oracao os moradores de itajai amam o porto qual e o sujeito','["Os moradores","De Itajaí","O porto","Os moradores de Itajaí","Amam"]',3,'O sujeito é o termo sobre o qual se declara algo. ''Os moradores de Itajaí'' é o sujeito simples (núcleo: moradores).','Banco legado perguntas.json',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('legacy-pt-009','7','Qual das frases abaixo apresenta um sujeito inexistente (oração sem sujeito)?','qual das frases abaixo apresenta um sujeito inexistente oracao sem sujeito','["Choveu canivetes ontem.","Havia muitos navios no porto.","Eles chegaram cedo.","Fui à prefeitura.","Precisa-se de serventes."]',1,'O verbo ''Haver'', quando significa ''existir'' ou indica tempo decorrido, é impessoal e não possui sujeito.','Banco legado perguntas.json',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('legacy-pt-010','7','Assinale a alternativa correta quanto à concordância verbal:','assinale a alternativa correta quanto a concordancia verbal','["Faziam dez anos que não o via.","Mais de um aluno faltaram.","Fui eu que fez o trabalho.","Houveram muitos acidentes.","Faz dez anos que não o via."]',4,'O verbo ''Fazer'', indicando tempo decorrido, é impessoal e deve ficar sempre no singular.','Banco legado perguntas.json',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('legacy-pt-011','7','Em ''O navio atracou no píer'', o termo ''no píer'' exerce a função sintática de:','em o navio atracou no pier o termo no pier exerce a funcao sintatica de','["Objeto Direto","Objeto Indireto","Adjunto Adverbial de Lugar","Sujeito","Complemento Nominal"]',2,'''No píer'' indica a circunstância de lugar onde a ação ocorreu, sendo um adjunto adverbial.','Banco legado perguntas.json',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('legacy-pt-012','7','Qual frase está pontuada corretamente?','qual frase esta pontuada corretamente','["O prefeito, viajou ontem.","Os alunos, estudaram muito.","Ontem, os funcionários limparam a praça.","Maria comprou: pão leite e café.","Eu gosto de ler, você de cantar."]',2,'A vírgula após ''Ontem'' marca o deslocamento de um adjunto adverbial curto (opcional, mas correta).','Banco legado perguntas.json',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('legacy-pt-013','7','Identifique a oração com verbo de ligação (predicado nominal):','identifique a oracao com verbo de ligacao predicado nominal','["A criança correu muito.","O dia está lindo.","O pássaro voou alto.","Comi uma maçã.","O navio partiu cedo."]',1,'O verbo ''estar'' liga o sujeito ''O dia'' a uma característica (lindo), formando um predicado nominal.','Banco legado perguntas.json',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('legacy-pt-014','7','Na frase ''Comprei o livro e o li'', o termo ''li'' possui qual tipo de objeto?','na frase comprei o livro e o li o termo li possui qual tipo de objeto','["Objeto Indireto","Objeto Direto (pronome ''o'')","Complemento Nominal","Agente da Passiva","Adjunto Adnominal"]',1,'O pronome oblíquo ''o'' substitui ''o livro'' e funciona como objeto direto do verbo ler.','Banco legado perguntas.json',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-1','8','Qual característica é indispensável para que uma oração seja considerada proposição lógica, segundo a lógica bivalente?','qual caracteristica e indispensavel para que uma oracao seja considerada proposicao logica segundo a logica bivalente','["Ser declarativa e admitir exatamente um valor lógico, verdadeiro ou falso.","Ser interrogativa e admitir qualquer número de respostas.","Conter obrigatoriamente uma variável.","Ser sempre verdadeira.","Conter um verbo no infinitivo."]',0,'Uma proposição lógica é uma oração declarativa à qual pode ser atribuído um, e apenas um, dos dois valores lógicos: verdadeiro ou falso.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Introdução às Proposições.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-2','8','Qual das alternativas apresenta uma proposição lógica?','qual das alternativas apresenta uma proposicao logica','["Feche a porta, por favor.","Qual é o horário da prova?","Itajaí é um município de Santa Catarina.","Estude mais!","Que dia bonito!"]',2,'A frase é declarativa e pode ser classificada como verdadeira ou falsa, satisfazendo o conceito de proposição.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Introdução às Proposições.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-3','8','Qual alternativa apresenta uma sentença que não é proposição por ser interrogativa?','qual alternativa apresenta uma sentenca que nao e proposicao por ser interrogativa','["A prova será realizada em Itajaí.","Itajaí fica em Santa Catarina.","2 + 2 = 4.","Qual é o horário da prova?","A questão está correta."]',3,'Perguntas não são orações declarativas às quais se atribua um único valor lógico.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Introdução às Proposições.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-4','8','Qual alternativa apresenta uma sentença que não é proposição por ser imperativa?','qual alternativa apresenta uma sentenca que nao e proposicao por ser imperativa','["O edital foi publicado.","Leia atentamente o enunciado.","3 é maior que 1.","A prova contém questões objetivas.","Itajaí possui um porto."]',1,'Uma ordem ou comando não é proposição lógica, mesmo contendo verbo, porque não é uma declaração com valor V ou F.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Introdução às Proposições.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-5','8','Na lógica bivalente, os únicos valores lógicos possíveis são:','na logica bivalente os unicos valores logicos possiveis sao','["verdadeiro e provavelmente verdadeiro","falso e indeterminado","verdadeiro e falso","sim e não necessariamente","certo, errado e indeterminado"]',2,'A lógica bivalente trabalha com exatamente dois valores: verdadeiro e falso.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Lógica Bivalente.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-6','8','A frase “x + 5 = 12”, sem qualquer informação sobre x, é classificada como:','a frase x 5 12 sem qualquer informacao sobre x e classificada como','["proposição verdadeira","proposição falsa","sentença aberta","bicondicional","tautologia"]',2,'O valor lógico depende do valor atribuído à variável x; portanto, trata-se de sentença aberta.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Proposições Simples e sentenças abertas.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-7','8','A sentença “x² = 9” pode ser considerada proposição, sem outras informações sobre x?','a sentenca x 9 pode ser considerada proposicao sem outras informacoes sobre x','["Sim, porque toda equação é proposição.","Não, porque o valor lógico depende de x.","Sim, porque é sempre verdadeira.","Não, porque toda sentença matemática é interrogativa.","Sim, porque possui apenas números."]',1,'Sem determinar ou quantificar x, o valor lógico de x² = 9 pode variar; por isso é sentença aberta.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Proposições Simples e sentenças abertas.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-8','8','Qual é o valor lógico de “7 + 3 = 10”?','qual e o valor logico de 7 3 10','["Verdadeiro","Falso","Indeterminado","Aberto","Bicondicional"]',0,'A igualdade é matematicamente correta, portanto a proposição é verdadeira.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, exemplos de proposições simples.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-9','8','Qual é o valor lógico de “12 > 20”?','qual e o valor logico de 12 20','["Verdadeiro","Falso","Indeterminado","Não proposicional","Simultaneamente V e F"]',1,'Como 12 não é maior que 20, a proposição é falsa.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, exemplos de proposições simples.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-10','8','Considere p: “O protocolo foi registrado”. Qual é a negação lógica de p?','considere p o protocolo foi registrado qual e a negacao logica de p','["O protocolo foi registrado novamente.","O protocolo talvez tenha sido registrado.","O protocolo não foi registrado.","O protocolo foi arquivado.","O protocolo será registrado."]',2,'A negação de uma proposição simples deve inverter seu valor lógico; aqui, “não foi registrado” é a negação de p.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Negação de Proposições Simples.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-11','8','Se p é verdadeira, então a negação de p é:','se p e verdadeira entao a negacao de p e','["verdadeira","falsa","indeterminada","simultaneamente verdadeira e falsa","uma sentença aberta"]',1,'A negação de uma proposição simples sempre apresenta valor lógico oposto ao da proposição original.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Negação de Proposições Simples.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-12','8','Se p é falsa, então ~p é:','se p e falsa entao p e','["falsa","verdadeira","indeterminada","necessariamente aberta","uma contradição"]',1,'A negação de uma proposição falsa é verdadeira.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Negação de Proposições Simples.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-13','8','A dupla negação de uma proposição p, representada por ~(~p), é logicamente equivalente a:','a dupla negacao de uma proposicao p representada por p e logicamente equivalente a','["p","~p","p ∧ ~p","p ∨ ~p","uma sentença aberta"]',0,'Duas negações consecutivas recuperam o valor lógico da proposição original.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Negação de Proposições Simples.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-14','8','Qual afirmação sobre um número par de negações está de acordo com o material?','qual afirmacao sobre um numero par de negacoes esta de acordo com o material','["Sempre produz valor oposto ao original.","É equivalente à proposição original.","Transforma proposição em sentença aberta.","Sempre produz uma contradição.","Elimina o valor lógico."]',1,'O material destaca que número par de negações mantém equivalência com a proposição original.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Negação de Proposições Simples.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-15','8','Considere p: “Ana estudou” e q: “Bruno revisou”. A expressão p ∧ q corresponde a:','considere p ana estudou e q bruno revisou a expressao p q corresponde a','["Ana estudou ou Bruno revisou.","Se Ana estudou, então Bruno revisou.","Ana estudou e Bruno revisou.","Ana estudou se, e somente se, Bruno revisou.","Ana não estudou e Bruno não revisou."]',2,'O conectivo ∧ representa conjunção, normalmente expressa pela palavra “e”.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Proposições Compostas.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-16','8','A conjunção p ∧ q é verdadeira quando:','a conjuncao p q e verdadeira quando','["p e q são verdadeiras.","p é verdadeira e q é falsa.","p é falsa e q é verdadeira.","p e q são falsas.","p e q têm valores diferentes."]',0,'A conjunção é verdadeira somente quando ambas as parcelas são verdadeiras.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Proposições Compostas.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-17','8','Se p é verdadeira e q é falsa, qual é o valor de p ∧ q?','se p e verdadeira e q e falsa qual e o valor de p q','["Verdadeiro","Falso","Indeterminado","Depende do contexto","Não é proposição"]',1,'Como uma conjunção exige que ambas sejam verdadeiras, V ∧ F resulta em falso.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Conjunção.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-18','8','Considere p: “O servidor protocolou o documento” e q: “O documento foi encaminhado”. A expressão p ∨ q representa:','considere p o servidor protocolou o documento e q o documento foi encaminhado a expressao p q representa','["O servidor protocolou e o documento foi encaminhado.","Se o servidor protocolou, então o documento foi encaminhado.","O servidor não protocolou ou o documento não foi encaminhado.","O servidor protocolou ou o documento foi encaminhado.","O servidor protocolou se, e somente se, o documento foi encaminhado."]',3,'A disjunção inclusiva ∨ corresponde ao conectivo “ou”.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Proposições Compostas.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-19','8','A disjunção inclusiva p ∨ q é falsa somente quando:','a disjuncao inclusiva p q e falsa somente quando','["p e q são verdadeiras.","p é verdadeira e q é falsa.","p é falsa e q é verdadeira.","p e q são falsas.","p e q têm valores diferentes."]',3,'Na disjunção inclusiva, basta uma das parcelas ser verdadeira; ela só é falsa quando ambas são falsas.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Disjunção Inclusiva.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-20','8','Se p é falsa e q é verdadeira, qual é o valor de p ∨ q?','se p e falsa e q e verdadeira qual e o valor de p q','["Verdadeiro","Falso","Indeterminado","Não proposicional","Simultaneamente V e F"]',0,'Na disjunção inclusiva, uma única parcela verdadeira já torna a expressão verdadeira.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Disjunção Inclusiva.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-21','8','Na disjunção exclusiva, representada no material por “ou...ou”, a proposição é falsa quando:','na disjuncao exclusiva representada no material por ou ou a proposicao e falsa quando','["ambas as parcelas são verdadeiras ou ambas são falsas","as parcelas têm valores diferentes","p é verdadeira e q é falsa","p é falsa e q é verdadeira","p é sempre verdadeira"]',0,'A disjunção exclusiva é falsa quando as duas parcelas têm o mesmo valor lógico.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Disjunção Exclusiva.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-22','8','Se p é verdadeira e q é falsa, a disjunção exclusiva “ou p ou q” é:','se p e verdadeira e q e falsa a disjuncao exclusiva ou p ou q e','["verdadeira","falsa","indeterminada","uma sentença aberta","necessariamente uma conjunção"]',0,'Como as parcelas têm valores diferentes, a disjunção exclusiva é verdadeira.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Disjunção Exclusiva.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-23','8','Considere a condicional p → q. Em qual situação ela é falsa?','considere a condicional p q em qual situacao ela e falsa','["p falsa e q falsa","p falsa e q verdadeira","p verdadeira e q falsa","p verdadeira e q verdadeira","quando p e q têm o mesmo valor"]',2,'A condicional é falsa somente no caso V → F.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Condicional.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-24','8','A expressão “Se o documento foi conferido, então será encaminhado” possui a forma lógica:','a expressao se o documento foi conferido entao sera encaminhado possui a forma logica','["p ∧ q","p ∨ q","p → q","p ↔ q","~p"]',2,'A estrutura “se..., então...” corresponde à condicional p → q.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Condicional.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-25','8','Se p é falsa e q é falsa, qual é o valor de p → q?','se p e falsa e q e falsa qual e o valor de p q','["Verdadeiro","Falso","Indeterminado","Não proposicional","Depende da ordem das palavras"]',0,'A única situação falsa da condicional é V → F; portanto F → F é verdadeira.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Condicional.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-26','8','Se p é verdadeira e q é verdadeira, qual é o valor de p → q?','se p e verdadeira e q e verdadeira qual e o valor de p q','["Falso","Verdadeiro","Indeterminado","Aberto","Contraditório"]',1,'A condicional V → V é verdadeira; somente V → F é falsa.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Condicional.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-27','8','A bicondicional p ↔ q é verdadeira quando:','a bicondicional p q e verdadeira quando','["p e q têm valores diferentes","p é verdadeira e q é falsa","p e q têm o mesmo valor lógico","p é sempre verdadeira","q é sempre falsa"]',2,'A bicondicional é verdadeira quando as duas parcelas apresentam o mesmo valor lógico.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Bicondicional.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-28','8','A expressão “p se, e somente se, q” corresponde a:','a expressao p se e somente se q corresponde a','["p ∧ q","p ∨ q","p → q","p ↔ q","~p ∨ q"]',3,'O conectivo “se, e somente se” representa a bicondicional.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Bicondicional.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-29','8','Se p é falsa e q é falsa, então p ↔ q é:','se p e falsa e q e falsa entao p q e','["falsa","verdadeira","indeterminada","uma sentença aberta","necessariamente uma disjunção"]',1,'Na bicondicional, valores iguais produzem resultado verdadeiro; F ↔ F é verdadeira.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Bicondicional.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-30','8','Se p é verdadeira e q é falsa, então p ↔ q é:','se p e verdadeira e q e falsa entao p q e','["verdadeira","falsa","indeterminada","uma conjunção verdadeira","uma sentença aberta"]',1,'Como os valores são diferentes, a bicondicional é falsa.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Bicondicional.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-31','8','Qual alternativa apresenta corretamente os cinco conectivos trabalhados no material?','qual alternativa apresenta corretamente os cinco conectivos trabalhados no material','["e; ou; ou...ou; se...então; se e somente se","e; porque; portanto; embora; quando","se; mas; logo; talvez; portanto","e; nem; contudo; apesar; como","ou; então; porque; desde; ainda"]',0,'O material apresenta conjunção, disjunção inclusiva, disjunção exclusiva, condicional e bicondicional.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Proposições Compostas.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-32','8','Considere p verdadeira e q verdadeira. Qual expressão é necessariamente falsa?','considere p verdadeira e q verdadeira qual expressao e necessariamente falsa','["p ∧ q","p ∨ q","p → q","p ↔ q","disjunção exclusiva de p e q"]',4,'Na disjunção exclusiva, parcelas com o mesmo valor lógico tornam a expressão falsa; V e V têm o mesmo valor.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Disjunção Exclusiva.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-33','8','Considere p falsa e q verdadeira. Qual expressão é falsa?','considere p falsa e q verdadeira qual expressao e falsa','["p ∧ q","p ∨ q","p → q","p ↔ q","disjunção exclusiva de p e q"]',3,'Na bicondicional, valores diferentes produzem falsidade; portanto F ↔ V é falsa.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Bicondicional.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-34','8','Considere p verdadeira e q falsa. Qual expressão é verdadeira?','considere p verdadeira e q falsa qual expressao e verdadeira','["p ∧ q","p ∨ q","p → q","p ↔ q","todas as anteriores"]',1,'Com V e F, a disjunção inclusiva é verdadeira, enquanto a conjunção, a condicional e a bicondicional são falsas.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, tabelas-verdade dos conectivos.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-35','8','Considere p falsa e q verdadeira. Qual expressão é verdadeira?','considere p falsa e q verdadeira qual expressao e verdadeira','["p ∧ q","p ∨ q","p ↔ q","~q","p ∧ ~q"]',1,'A disjunção inclusiva é verdadeira quando pelo menos uma das parcelas é verdadeira.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Disjunção Inclusiva.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-36','8','Se p: “A prova começou” é verdadeira, qual é o valor lógico de ~p?','se p a prova comecou e verdadeira qual e o valor logico de p','["Verdadeiro","Falso","Indeterminado","Verdadeiro e falso","Não é possível negar uma proposição"]',1,'A negação apresenta valor lógico oposto ao da proposição original.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Negação de Proposições Simples.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-37','8','Qual das frases abaixo é uma sentença aberta?','qual das frases abaixo e uma sentenca aberta','["A prova começa às oito horas.","7 é maior que 3.","x é maior que 3.","Itajaí fica em Santa Catarina.","O edital foi publicado."]',2,'O valor lógico de “x é maior que 3” depende do valor atribuído à variável x.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Sentenças Abertas.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-38','8','A frase “Existe um número natural x tal que x + 9 = 10” pode ser tratada como proposição porque:','a frase existe um numero natural x tal que x 9 10 pode ser tratada como proposicao porque','["o valor lógico depende de uma variável sem quantificação","há uma afirmação declarativa com existência quantificada e valor lógico determinável","toda equação é sempre proposição","ela é uma pergunta matemática","não possui qualquer valor lógico"]',1,'A presença de quantificação elimina a indeterminação da variável e permite avaliar a afirmação como verdadeira ou falsa.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, discussão sobre sentenças abertas e quantificadores.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-new-39','8','Qual alternativa contém um quantificador mencionado no material?','qual alternativa contem um quantificador mencionado no material','["talvez","porque","todo","porém","logo"]',2,'“Todo” é exemplo de quantificador; o material também cita “para todo”, “qualquer”, “nenhum” e “existe”.','PDF de Raciocínio Lógico e Resolução de Problemas – Itajaí/SC 2026, seção Introdução às Proposições e Quantificadores.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
