INSERT INTO perguntas (id,tema,pergunta,pergunta_normalizada,opcoes,correta,explicacao,base,dificuldade,ativa,origem_tipo,origem_banca,origem_orgao,origem_ano,origem_cargo,origem_numero,origem_url) VALUES ('8-v3-02','8','Se ''Se o sistema falha, então o atendimento atrasa'' é verdadeira e o atendimento não atrasou, conclui-se logicamente que:','se se o sistema falha entao o atendimento atrasa e verdadeira e o atendimento nao atrasou conclui se logicamente que','["o sistema falhou","o sistema não falhou","o sistema pode ter falhado ou não","o atendimento falhou"]',1,'Aplicação de modus tollens: p→q e ¬q implicam ¬p.','Lógica proposicional.',2,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL) ON CONFLICT(id) DO UPDATE SET tema=excluded.tema,pergunta=excluded.pergunta,pergunta_normalizada=excluded.pergunta_normalizada,opcoes=excluded.opcoes,correta=excluded.correta,explicacao=excluded.explicacao,base=excluded.base,dificuldade=excluded.dificuldade,ativa=excluded.ativa,origem_tipo=excluded.origem_tipo,origem_banca=excluded.origem_banca,origem_orgao=excluded.origem_orgao,origem_ano=excluded.origem_ano,origem_cargo=excluded.origem_cargo,origem_numero=excluded.origem_numero,origem_url=excluded.origem_url,atualizado_em=CURRENT_TIMESTAMP;
